(function() {
    'use strict';

    class InclusionFinancieraAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Inclusión Financiera';
            this.version = '1.1.0';
            this.BRIEFINGS = {
                en: [
                    '<strong>SBDH Inspection Letter Received</strong><br><br>The Superintendencia de Bancos de Honduras has sent an inspection letter questioning the Remittance-Based Lending program. They demand evidence that the program meets proper underwriting standards within 60 days.<br><br>Key regulatory concerns: (1) No formal payment-capacity assessment; (2) Remittances are not recognized collateral; (3) Remitter authorization is missing; (4) Alternative scoring methodology is unvalidated.<br><br><strong>Decide:</strong> How much to invest in regulatory compliance, and what legal strategy to adopt.',
                    '<strong>6-Month Portfolio Performance Data</strong><br><br>Pilot data is in: 360 of 400 clients are current (90%), 25 are 30+ days past due (6.25%), and 15 are in default (3.75%). Analysis shows 12 of 15 defaults were caused by remittance interruptions (job loss abroad). The annualized default rate extrapolates to ~7.5%, compared to the 5-8% banking average in Honduras.<br><br><strong>Decide:</strong> What monitoring system to deploy and whether to introduce remittance interruption insurance.',
                    '<strong>Social Impact Assessment</strong><br><br>Early results show the program is transforming lives: 400 previously unbanked people now have formal credit access, 60 new local businesses have been started, and average client income rose 21% (from $1,200 to $1,450/month). However, if defaults rise above 15%, vulnerable clients could end up worse off.<br><br><strong>Decide:</strong> How much to invest in social programs and where to focus efforts.',
                    '<strong>Scale-Up Planning</strong><br><br>Assuming regulatory approval, the program can scale from 400 to up to 8,000 clients (the full unbanked population in the Choluteca region). At scale, the portfolio would reach $24M with projected net income of $1.4M/year. But scaling requires significant technology investment and carries operational risk.<br><br><strong>Decide:</strong> Set the growth target and technology investment level.'
                ],
                es: [
                    '<strong>Carta de Inspección de la SBDH</strong><br><br>La Superintendencia de Bancos de Honduras ha enviado una carta de inspección cuestionando el programa de Préstamos Basados en Remesas. Exigen evidencia de que el programa cumple estándares de evaluación crediticia en 60 días.<br><br>Preocupaciones regulatorias clave: (1) Sin evaluación formal de capacidad de pago; (2) Las remesas no son garantía reconocida; (3) Falta autorización de remitentes; (4) Metodología de scoring alternativo no validada.<br><br><strong>Decida:</strong> Cuánto invertir en cumplimiento regulatorio y qué estrategia legal adoptar.',
                    '<strong>Datos de Rendimiento del Portafolio a 6 Meses</strong><br><br>Los datos del piloto están listos: 360 de 400 clientes están al día (90%), 25 tienen mora de 30+ días (6.25%) y 15 están en default (3.75%). El análisis muestra que 12 de 15 defaults fueron causados por interrupción de remesas (pérdida de empleo en el exterior). La tasa de default anualizada se extrapola a ~7.5%, comparada con el promedio bancario de 5-8% en Honduras.<br><br><strong>Decida:</strong> Qué sistema de monitoreo implementar y si introducir un seguro contra interrupción de remesas.',
                    '<strong>Evaluación de Impacto Social</strong><br><br>Los resultados tempranos muestran que el programa está transformando vidas: 400 personas previamente sin acceso bancario ahora tienen crédito formal, se han creado 60 nuevos negocios locales y el ingreso promedio de los clientes aumentó 21% (de $1,200 a $1,450/mes). Sin embargo, si los defaults suben por encima del 15%, los clientes vulnerables podrían quedar peor.<br><br><strong>Decida:</strong> Cuánto invertir en programas sociales y dónde enfocar los esfuerzos.',
                    '<strong>Plan de Escalamiento</strong><br><br>Asumiendo aprobación regulatoria, el programa puede escalar de 400 a 8,000 clientes (toda la población sin bancarizar de la región de Choluteca). A escala, el portafolio alcanzaría $24M con ingresos netos proyectados de $1.4M/año. Pero escalar requiere inversión tecnológica significativa y conlleva riesgo operacional.<br><br><strong>Decida:</strong> Establezca la meta de crecimiento y el nivel de inversión tecnológica.'
                ]
            };
        }

        _score(ds){var s=0;if(ds.cash>300000)s+=25;else if(ds.cash>200000)s+=15;if(ds.regulatoryStatus==='approved')s+=30;else if(ds.regulatoryStatus==='conditional')s+=15;if(ds.defaultRate<3)s+=20;else if(ds.defaultRate<5)s+=10;if(ds.socialScore>70)s+=25;else if(ds.socialScore>40)s+=12;return s;}
        formatCompletionMessage(summary){var isEs=this._getLang()==='es';var s=(summary&&typeof summary.score==='number')?summary.score:0;var perf=(summary&&summary.performance)||'';var ins=(summary&&summary.insights)||[];var scoreLabel=isEs?'Puntuación de Inclusión Financiera':'Financial Inclusion Score';var periodsLabel=isEs?'rondas completadas':'rounds completed';var thanks=isEs?'Gracias por participar.':'Thank you for participating.';var color=s>=80?'#2e7d32':(s>=55?'#f9a825':(s>=35?'#ef6c00':'#c62828'));var items=ins.map(function(t){return '<li>'+t+'</li>';}).join('');var insBlock=items?('<ul style="text-align:left;margin-top:12px;display:inline-block;">'+items+'</ul>'):'';return '<div class="completion-message text-center p-4">'+'<div style="font-size:2.6rem;font-weight:800;color:'+color+';">'+s+'/100</div>'+'<p class="lead" style="margin:4px 0 2px;">'+scoreLabel+'</p>'+'<p style="font-weight:600;color:'+color+';">'+perf+'</p>'+'<p class="text-muted" style="margin-bottom:6px;">'+(summary.totalPeriods||0)+' '+periodsLabel+'</p>'+insBlock+'<hr class="my-3"><p class="text-muted">'+thanks+'</p></div>';}
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 300000,
                    portfolioValue: 1200000,
                    defaultRate: 3.75,
                    clientCount: 400,
                    socialScore: 20,
                    regulatoryScore: 0,
                    regulatoryStatus: 'pending',
                    newBusinesses: 50,
                    avgClientIncome: 1200,
                    cashHistory: [],
                    portfolioHistory: [],
                    defaultHistory: [],
                    socialHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    complianceBudget: 100000,
                    legalApproach: 2,
                    monitoringLevel: 2,
                    insuranceRate: 1.5,
                    socialBudget: 50000,
                    programFocus: 2,
                    growthTarget: 4000,
                    techBudget: 200000
                };
            }
            this._setupSliders();
            this._updateBriefing(state);
        }

        _setupSliders() {
            var compSlider = document.getElementById('complianceBudgetInput');
            if (compSlider) {
                compSlider.addEventListener('input', function() {
                    var el = document.getElementById('complianceBudgetShow');
                    if (el) el.textContent = '$' + parseInt(this.value).toLocaleString();
                });
            }
            var insSlider = document.getElementById('insuranceRateInput');
            if (insSlider) {
                insSlider.addEventListener('input', function() {
                    var el = document.getElementById('insuranceRateShow');
                    if (el) el.textContent = parseFloat(this.value).toFixed(2) + '%';
                });
            }
            var socSlider = document.getElementById('socialBudgetInput');
            if (socSlider) {
                socSlider.addEventListener('input', function() {
                    var el = document.getElementById('socialBudgetShow');
                    if (el) el.textContent = '$' + parseInt(this.value).toLocaleString();
                });
            }
            var growthSlider = document.getElementById('growthTargetInput');
            if (growthSlider) {
                growthSlider.addEventListener('input', function() {
                    var el = document.getElementById('growthTargetShow');
                    if (el) el.textContent = parseInt(this.value).toLocaleString();
                });
            }
            var techSlider = document.getElementById('techBudgetInput');
            if (techSlider) {
                techSlider.addEventListener('input', function() {
                    var el = document.getElementById('techBudgetShow');
                    if (el) el.textContent = '$' + parseInt(this.value).toLocaleString();
                });
            }
        }

        _getLang() {
            if (window.mySimulation && window.mySimulation.currentLanguage) return window.mySimulation.currentLanguage;
            var htmlLang = document.documentElement.lang;
            if (htmlLang && htmlLang.substring(0, 2) === 'es') return 'es';
            return 'en';
        }

        _updateBriefing(state) {
            if ((state.currentPeriod || 1) > 4) {
                var _p = ['round1Panel','round2Panel','round3Panel','round4Panel'];
                for (var _i = 0; _i < _p.length; _i++) { var _el = document.getElementById(_p[_i]); if (_el) _el.style.display = 'none'; }
                var _b = document.getElementById('briefingText');
                if (_b) _b.innerHTML = (this._getLang() === 'es') ? '<strong>Programa completado.</strong> Has finalizado las 4 rondas. Revisa tu puntuación y el resumen final.' : '<strong>Program complete.</strong> You have finished all 4 rounds. Review your score and final summary.';
                return;
            }
            var period = Math.min((state.currentPeriod || 1), 4);
            var idx = period - 1;
            var lang = this._getLang();
            var briefings = this.BRIEFINGS[lang] || this.BRIEFINGS['en'];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = briefings[idx];

            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var i = 0; i < panels.length; i++) {
                var panel = document.getElementById(panels[i]);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var compInput = document.getElementById('complianceBudgetInput');
                if (compInput) decisions.complianceBudget = parseInt(compInput.value);
                var legalInput = document.getElementById('legalApproachInput');
                if (legalInput) decisions.legalApproach = parseInt(legalInput.value);
                if (decisions.complianceBudget < 50000 || decisions.complianceBudget > 150000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_warning'), 'warning');
                    return false;
                }
            } else if (period === 2) {
                var monInput = document.getElementById('monitoringLevelInput');
                if (monInput) decisions.monitoringLevel = parseInt(monInput.value);
                var insInput = document.getElementById('insuranceRateInput');
                if (insInput) decisions.insuranceRate = parseFloat(insInput.value);
            } else if (period === 3) {
                var socInput = document.getElementById('socialBudgetInput');
                if (socInput) decisions.socialBudget = parseInt(socInput.value);
                var focusInput = document.getElementById('programFocusInput');
                if (focusInput) decisions.programFocus = parseInt(focusInput.value);
                if (decisions.socialBudget > window.mySimulation.state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('insufficient_funds'), 'warning');
                    return false;
                }
            } else if (period === 4) {
                var growthInput = document.getElementById('growthTargetInput');
                if (growthInput) decisions.growthTarget = parseInt(growthInput.value);
                var techInput = document.getElementById('techBudgetInput');
                if (techInput) decisions.techBudget = parseInt(techInput.value);
                if (decisions.techBudget > window.mySimulation.state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('insufficient_funds'), 'warning');
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var investment = 0;
            var income = 0;
            var netResult = 0;

            if (period === 1) {
                investment = d.complianceBudget;
                var budgetFactor = (d.complianceBudget - 50000) / 100000 * 30;
                var legalFactor = d.legalApproach === 1 ? 5 : (d.legalApproach === 2 ? 20 : 35);
                ds.regulatoryScore = Math.min(100, Math.round(40 + budgetFactor + legalFactor));
                if (ds.regulatoryScore >= 85) {
                    ds.regulatoryStatus = 'approved';
                } else if (ds.regulatoryScore >= 65) {
                    ds.regulatoryStatus = 'conditional';
                } else {
                    ds.regulatoryStatus = 'review';
                }
                var interestIncome = Math.round(ds.portfolioValue * 0.15 / 2);
                var defaultLoss = Math.round(ds.portfolioValue * ds.defaultRate / 100);
                var adminCost = 40000;
                income = interestIncome - defaultLoss - adminCost;
                netResult = income - investment;
                ds.cash += netResult;

            } else if (period === 2) {
                var monitorCost = d.monitoringLevel === 1 ? 10000 : (d.monitoringLevel === 2 ? 25000 : 50000);
                var defaultReduction = d.monitoringLevel === 1 ? 0.3 : (d.monitoringLevel === 2 ? 1.2 : 2.5);
                var insuranceIncome = Math.round(ds.portfolioValue * d.insuranceRate / 100 / 2);
                ds.defaultRate = Math.max(1.0, ds.defaultRate - defaultReduction);
                if (d.insuranceRate >= 2.0) {
                    ds.defaultRate = Math.max(0.5, ds.defaultRate - 0.5);
                }
                var interestIncome2 = Math.round(ds.portfolioValue * 0.15 / 2);
                var defaultLoss2 = Math.round(ds.portfolioValue * ds.defaultRate / 100);
                var adminCost2 = 40000;
                investment = monitorCost;
                income = interestIncome2 + insuranceIncome - defaultLoss2 - adminCost2;
                netResult = income - investment;
                ds.cash += netResult;

            } else if (period === 3) {
                investment = d.socialBudget;
                var socialGain = Math.round((d.socialBudget / 100000) * 25);
                if (d.programFocus === 1) {
                    ds.defaultRate = Math.max(0.5, ds.defaultRate - 1.0);
                    socialGain += 5;
                } else if (d.programFocus === 2) {
                    var newBiz = Math.round((d.socialBudget / 10000) * 6);
                    ds.newBusinesses += newBiz;
                    ds.avgClientIncome += Math.round(newBiz * 4.2);
                    socialGain += 15;
                } else {
                    socialGain += 20;
                    ds.avgClientIncome += 80;
                }
                ds.socialScore = Math.min(100, ds.socialScore + socialGain);
                var interestIncome3 = Math.round(ds.portfolioValue * 0.15 / 2);
                var defaultLoss3 = Math.round(ds.portfolioValue * ds.defaultRate / 100);
                income = interestIncome3 - defaultLoss3 - 40000;
                netResult = income - investment;
                ds.cash += netResult;

            } else if (period === 4) {
                investment = d.techBudget;
                var expansionCost = Math.round(d.growthTarget * 12.5);
                investment += expansionCost;
                var regMultiplier = ds.regulatoryStatus === 'approved' ? 1.0 : (ds.regulatoryStatus === 'conditional' ? 0.6 : 0.25);
                var effectiveGrowth = Math.round(d.growthTarget * regMultiplier);
                ds.clientCount += effectiveGrowth;
                var newPortfolio = effectiveGrowth * 3000;
                ds.portfolioValue += newPortfolio;
                var techEfficiency = Math.min(0.4, d.techBudget / 1000000);
                var scaleAdminCost = Math.round(ds.clientCount * 200 * (1 - techEfficiency));
                var totalInterest = Math.round(ds.portfolioValue * 0.15);
                var totalDefaultLoss = Math.round(ds.portfolioValue * ds.defaultRate / 100);
                income = totalInterest - totalDefaultLoss - scaleAdminCost;
                netResult = income - investment;
                ds.cash += netResult;
                ds.socialScore = Math.min(100, ds.socialScore + Math.round(effectiveGrowth / 200));
            }

            ds.cashHistory.push(ds.cash);
            ds.portfolioHistory.push(ds.portfolioValue);
            ds.defaultHistory.push(ds.defaultRate);
            ds.socialHistory.push(ds.socialScore);
            var __sc = this._score(ds);
            ds.score = __sc;
            ds.performance = { overallScore: __sc, grade: (__sc>=80?'Excellent':(__sc>=55?'Good':(__sc>=35?'Adequate':'Needs Improvement'))) };


            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: period,
                investment: investment,
                income: income,
                netResult: netResult,
                defaultRate: ds.defaultRate,
                socialScore: ds.socialScore,
                cash: ds.cash,
                portfolioValue: ds.portfolioValue,
                clientCount: ds.clientCount,
                regulatoryStatus: ds.regulatoryStatus,
                overallScore: __sc,
                score: __sc
            };
        }

