        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastState = history[history.length - 1];
            var finalCash = lastState.results ? lastState.results.cash : 0;
            var finalSocial = lastState.results ? lastState.results.socialScore : 0;
            var finalDefault = lastState.results ? lastState.results.defaultRate : 10;
            var finalReg = lastState.results ? lastState.results.regulatoryStatus : 'review';
            var totalInvested = history.reduce(function(s, r) { return s + (r.results ? r.results.investment : 0); }, 0);
            var totalIncome = history.reduce(function(s, r) { return s + (r.results ? r.results.income : 0); }, 0);

            var score = this._score({ cash: finalCash, regulatoryStatus: finalReg, defaultRate: finalDefault, socialScore: finalSocial });

            var __es = this._getLang() === 'es';
            var performance = __es ? 'Necesita Mejorar' : 'Needs Improvement';
            if (score >= 80) performance = __es ? 'Excelente' : 'Excellent';
            else if (score >= 55) performance = __es ? 'Buena' : 'Good';
            else if (score >= 35) performance = __es ? 'Adecuada' : 'Adequate';

            var insights = [];
            if (finalReg === 'approved') {
                insights.push(__es ? 'Aprobación regulatoria asegurada: estrategia de cumplimiento sólida.' : 'Regulatory approval secured — strong compliance strategy.');
            } else {
                insights.push(__es ? 'No se logró la aprobación regulatoria: considere invertir más en cumplimiento y estrategia legal.' : 'Regulatory approval was not achieved — consider investing more in compliance and legal strategy.');
            }
            if (finalDefault < 3) {
                insights.push(__es ? 'Tasa de mora bien controlada gracias a un monitoreo eficaz.' : 'Default rate well-controlled through effective monitoring.');
            }
            if (finalSocial > 60) {
                insights.push(__es ? 'Fuerte impacto social: se logró una inclusión financiera significativa.' : 'Strong social impact — meaningful financial inclusion achieved.');
            }
            if (finalCash < 200000) {
                insights.push(__es ? 'Las reservas de capital son bajas: equilibre la inversión con la sostenibilidad.' : 'Capital reserves are low — balance investment with sustainability.');
            }

            return {
                score: score,
                performance: performance,
                totalInvested: totalInvested,
                totalIncome: totalIncome,
                finalCash: finalCash,
                finalSocial: finalSocial,
                finalDefault: finalDefault,
                regulatoryOutcome: finalReg,
                insights: insights
            };
        }

